<?php
declare(strict_types=1);require dirname(__DIR__,2).'/app/bootstrap.php';require dirname(__DIR__,2).'/vendor/autoload.php';use App\Auth;use App\Security;use App\Admin;
$user=Auth::requireUser();if(($user['role_name']??'')!=='super_admin'){http_response_code(403);exit('هذه الصفحة متاحة للمدير الرئيسي فقط.');}$pdo=db();$error='';$keys=['store_name'=>'اسم المتجر','phone'=>'رقم الهاتف','whatsapp'=>'رقم واتساب','email'=>'البريد الإلكتروني','address'=>'العنوان','delivery_fee'=>'رسوم التوصيل (ريال)','footer_about'=>'نبذة الفوتر','hero_title'=>'عنوان الواجهة الرئيسية','hero_subtitle'=>'وصف الواجهة الرئيسية'];
if($_SERVER['REQUEST_METHOD']==='POST'){Security::requireCsrf();try{foreach($keys as $key=>$label){$value=trim((string)($_POST[$key]??''));if($key==='delivery_fee'&&(!is_numeric($value)||(float)$value<0||(float)$value>10000))throw new RuntimeException('رسوم التوصيل غير صحيحة.');if(mb_strlen($value)>1000)throw new RuntimeException('إحدى القيم أطول من الحد المسموح.');$q=$pdo->prepare("INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)");$q->execute([$key,$value]);}Admin::audit('settings.update','settings',null);header('Location: settings.php?saved=1');exit;}catch(Throwable $e){$error=$e instanceof RuntimeException?$e->getMessage():'تعذر حفظ الإعدادات.';}}
$values=[];$q=$pdo->query("SELECT setting_key,setting_value FROM settings");foreach($q->fetchAll() as $row)$values[$row['setting_key']]=$row['setting_value'];
?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>إعدادات المتجر</title><link rel="stylesheet" href="../assets/css/store.css"><style>.wrap{max-width:850px;margin:30px auto;padding:0 16px}.panel{background:#111;border:1px solid #49371c;border-radius:14px;padding:20px}.fields{display:grid;grid-template-columns:1fr 1fr;gap:14px}.fields label{display:block}.fields input,.fields textarea{width:100%;padding:11px;background:#080808;color:white;border:1px solid #49371c;border-radius:8px;font:inherit}.fields textarea{min-height:90px}@media(max-width:600px){.fields{grid-template-columns:1fr}}</style></head><body><main class="wrap"><a class="text-link" href="index.php">← لوحة التحكم</a><h1>إعدادات المتجر</h1><?php if($error):?><div class="notice"><?=e($error)?></div><?php endif;?><?php if(isset($_GET['saved'])):?><div class="notice">تم حفظ الإعدادات.</div><?php endif;?><section class="panel"><form method="post"><input type="hidden" name="_csrf" value="<?=e(Security::csrfToken())?>"><div class="fields"><?php foreach($keys as $key=>$label):?><label><?=e($label)?><?php if(in_array($key,['footer_about','hero_subtitle','address'],true)):?><textarea name="<?=e($key)?>"><?=e($values[$key]??'')?></textarea><?php else:?><input name="<?=e($key)?>" value="<?=e($values[$key]??($key==='delivery_fee'?'0':''))?>" <?=($key==='delivery_fee'?'type="number" min="0" step=".01"':'')?>></label><?php endif;?></label><?php endforeach;?></div><p><button class="btn btn-gold">حفظ الإعدادات</button></p></form></section></main></body></html>